use clap::{Parser, ValueEnum};
use std::time::{Duration, Instant};
use std::collections::HashMap;
use serde::Serialize;
use futures::stream::StreamExt;
use hyper::{Client, Request, Body, StatusCode};
use hyper::client::HttpConnector;
use hyper_tls::HttpsConnector;
use std::sync::Arc;
use tokio::sync::Semaphore;
use hdrhistogram::Histogram;

#[derive(ValueEnum, Clone, Debug, Copy, PartialEq, Eq)]
enum OutputFormat {
    Text,
    Json,
    Csv,
    Quiet,
}

#[derive(Parser, Debug)]
#[command(name = "oha", about = "Ohayou(おはよう), HTTP load generator, inspired by rakyll/hey with tui animation.")]
struct Args {
    #[arg(help = "Target URL or file with multiple URLs.")]
    url: String,

    #[arg(short = 'n', default_value = "200", help = "Number of requests to run.")]
    n_requests: String,

    #[arg(short = 'c', default_value = "50", help = "Number of connections to run concurrently.")]
    n_connections: usize,

    #[arg(short = 'p', default_value = "1", help = "Number of parallel requests to send on HTTP/2.")]
    n_http2_parallel: usize,

    #[arg(short = 'z', help = "Duration of application to send requests.")]
    duration: Option<String>,

    #[arg(short = 'w', long, help = "When the duration is reached, ongoing requests are waited")]
    wait_ongoing_requests_after_deadline: bool,

    #[arg(short = 'q', help = "Rate limit for all, in queries per second (QPS)")]
    query_per_second: Option<f64>,

    #[arg(long, help = "Introduce delay between a predefined number of requests.")]
    burst_delay: Option<String>,

    #[arg(long, default_value = "1", help = "Rates of requests for burst. Default is 1")]
    burst_rate: usize,

    #[arg(long, help = "Generate URL by rand_regex crate")]
    rand_regex_url: bool,

    #[arg(long, help = "Read the URLs to query from a file")]
    urls_from_file: bool,

    #[arg(long, default_value = "4", help = "A parameter for the '--rand-regex-url'")]
    max_repeat: usize,

    #[arg(long, help = "No realtime tui")]
    no_tui: bool,

    #[arg(long, default_value = "16", help = "Frame per second for tui.")]
    fps: usize,

    #[arg(short = 'm', long, default_value = "GET", help = "HTTP method")]
    method: String,

    #[arg(short = 'H', help = "Custom HTTP header. Examples: -H \"foo: bar\"")]
    headers: Vec<String>,

    #[arg(short = 't', help = "Timeout for each request. Default to infinite.")]
    timeout: Option<String>,

    #[arg(short = 'o', long, help = "Output file to write the results to.")]
    output: Option<String>,

    #[arg(long, default_value = "text", help = "Output format")]
    output_format: OutputFormat,

    #[arg(short = 'V', long, help = "Print version")]
    version: bool,
}

fn parse_count(s: &str) -> usize {
    let s = s.to_lowercase();
    if s.ends_with('k') {
        (s[..s.len() - 1].parse::<f64>().unwrap_or(0.0) * 1_000.0) as usize
    } else if s.ends_with('m') {
        (s[..s.len() - 1].parse::<f64>().unwrap_or(0.0) * 1_000_000.0) as usize
    } else {
        s.parse::<usize>().unwrap_or(0)
    }
}

fn parse_duration(s: &str) -> Duration {
    if s.ends_with("ms") {
        Duration::from_millis(s[..s.len() - 2].parse().unwrap_or(0))
    } else if s.ends_with('s') {
        Duration::from_secs(s[..s.len() - 1].parse().unwrap_or(0))
    } else if s.ends_with('m') {
        Duration::from_secs(s[..s.len() - 1].parse::<u64>().unwrap_or(0) * 60)
    } else if s.ends_with('h') {
        Duration::from_secs(s[..s.len() - 1].parse::<u64>().unwrap_or(0) * 3600)
    } else {
        Duration::from_secs(s.parse().unwrap_or(0))
    }
}

#[derive(Debug, Clone)]
struct RequestResult {
    duration: Duration,
    status: Option<StatusCode>,
    error: Option<String>,
    bytes: usize,
}

struct Stats {
    histogram: Histogram<u64>,
    status_codes: HashMap<u16, usize>,
    errors: HashMap<String, usize>,
    total_bytes: usize,
    start_time: Instant,
    end_time: Instant,
}

impl Stats {
    fn new() -> Self {
        Self {
            histogram: Histogram::<u64>::new_with_bounds(1, 60_000_000, 3).unwrap(),
            status_codes: HashMap::new(),
            errors: HashMap::new(),
            total_bytes: 0,
            start_time: Instant::now(),
            end_time: Instant::now(),
        }
    }

    fn add(&mut self, result: RequestResult) {
        if result.error.is_none() {
            self.histogram.record(result.duration.as_nanos() as u64).unwrap_or(());
            if let Some(status) = result.status {
                *self.status_codes.entry(status.as_u16()).or_insert(0) += 1;
            }
        } else if let Some(err) = result.error {
            *self.errors.entry(err).or_insert(0) += 1;
        }
        self.total_bytes += result.bytes;
    }
}

#[tokio::main]
async fn main() {
    let args = Args::parse();
    if args.version {
        println!("oha 1.12.1");
        return;
    }

    let n_requests = parse_count(&args.n_requests);
    let n_connections = args.n_connections;
    let url = Arc::new(args.url.clone());

    let https = HttpsConnector::new();
    let client = Client::builder().build::<_, Body>(https);
    let client = Arc::new(client);

    let (tx, mut rx) = tokio::sync::mpsc::channel(n_requests);
    let semaphore = Arc::new(Semaphore::new(n_connections));

    let start = Instant::now();

    let mut tasks = Vec::new();
    for _ in 0..n_requests {
        let permit = semaphore.clone().acquire_owned().await.unwrap();
        let tx = tx.clone();
        let client = client.clone();
        let url = url.clone();
        let method = args.method.clone();

        tasks.push(tokio::spawn(async move {
            let req_start = Instant::now();
            let method = hyper::Method::from_bytes(method.as_bytes()).unwrap_or(hyper::Method::GET);
            let req = Request::builder()
                .method(method)
                .uri(url.as_str())
                .header("user-agent", "oha/1.12.1")
                .body(Body::empty())
                .unwrap();

            let res = client.request(req).await;
            let duration = req_start.elapsed();

            let result = match res {
                Ok(mut response) => {
                    let mut bytes = 0;
                    while let Some(chunk) = response.body_mut().next().await {
                        if let Ok(chunk) = chunk {
                            bytes += chunk.len();
                        }
                    }
                    RequestResult {
                        duration,
                        status: Some(response.status()),
                        error: None,
                        bytes,
                    }
                }
                Err(e) => RequestResult {
                    duration,
                    status: None,
                    error: Some(e.to_string()),
                    bytes: 0,
                },
            };
            let _ = tx.send(result).await;
            drop(permit);
        }));
    }

    drop(tx);

    let mut stats = Stats::new();
    stats.start_time = start;
    while let Some(res) = rx.recv().await {
        stats.add(res);
    }
    stats.end_time = Instant::now();

    print_summary(&stats);
}

fn print_summary(stats: &Stats) {
    let total_duration = stats.end_time.duration_since(stats.start_time);
    let total_requests: usize = stats.status_codes.values().sum::<usize>() + stats.errors.values().sum::<usize>();
    let success_requests: usize = stats.status_codes.get(&200).cloned().unwrap_or(0); // This is simplified

    println!("Summary:");
    println!("  Success rate:	{:.2}%", (success_requests as f64 / total_requests as f64) * 100.0);
    println!("  Total:	{:.4} ms", total_duration.as_secs_f64() * 1000.0);
    println!("  Slowest:	{:.4} ms", stats.histogram.max() as f64 / 1_000_000.0);
    println!("  Fastest:	{:.4} ms", stats.histogram.min() as f64 / 1_000_000.0);
    println!("  Average:	{:.4} ms", stats.histogram.mean() / 1_000_000.0);
    println!("  Requests/sec:	{:.4}", total_requests as f64 / total_duration.as_secs_f64());
    println!("");
    println!("  Total data:	{} B", stats.total_bytes);
}
EOF
"}

