        Some("us") => (nanos / 1_000.0, "us"),
        Some("ms") => (nanos / 1_000_000.0, "ms"),
        Some("s") => (nanos / 1_000_000_000.0, "s"),
        _ => {
            if nanos < 1_000.0 {
                (nanos, "ns")
            } else if nanos < 1_000_000.0 {
                (nanos / 1_000.0, "us")
            } else if nanos < 1_000_000_000.0 {
                (nanos / 1_000_000.0, "ms")
            } else {
                (nanos / 1_000_000_000.0, "s")
            }
        }
    };
    format!("{:.4} {}", val, u)
