    codes.sort_by_key(|a| a.0);
    for (code, count) in codes {
        println!("  [{}] {} responses", code, count);
    }

    if !stats.errors.is_empty() {
        println!("\nError distribution:");
        for (err, count) in &stats.errors {
            println!("  [{}] {}", count, err);
        }
    }
}

#[tokio::main]
async fn main() {
    let args = Args::parse();
    if args.version {
        println!("oha 1.12.1");
        return;
    }

    let n_requests = parse_count(&args.n_requests);
    let n_connections = args.n_connections;
    let url = Arc::new(args.url.clone());

    let https = HttpsConnector::new();
    let client = Client::builder().build::<_, Body>(https);
    let client = Arc::new(client);

    let (tx, mut rx) = tokio::sync::mpsc::channel(1000);
    let semaphore = Arc::new(Semaphore::new(n_connections));

    let start = Instant::now();
    let duration_limit = args.duration.as_deref().map(parse_duration);

    let tx_clone = tx.clone();
    let client_clone = client.clone();
    let url_clone = url.clone();
    let method_clone = args.method.clone();

    let mut stats = Stats::new();
    stats.start_time = start;

    tokio::spawn(async move {
        let mut count = 0;
        loop {
            if let Some(limit) = duration_limit {
                if start.elapsed() >= limit {
                    break;
                }
            } else if count >= n_requests {
                break;
            }

            let permit = semaphore.clone().acquire_owned().await.unwrap();
            let tx = tx_clone.clone();
            let client = client_clone.clone();
            let url = url_clone.clone();
            let method = method_clone.clone();

            tokio::spawn(async move {
                let req_start = Instant::now();
                let method = hyper::Method::from_bytes(method.as_bytes()).unwrap_or(hyper::Method::GET);
                let req = Request::builder()
                    .method(method)
                    .uri(url.as_str())
                    .header("user-agent", "oha/1.12.1")
                    .body(Body::empty())
                    .unwrap();

                let res = client.request(req).await;
                let duration = req_start.elapsed();

                let result = match res {
                    Ok(mut response) => {
                        let mut bytes = 0;
                        while let Some(chunk) = response.body_mut().next().await {
                            if let Ok(chunk) = chunk {
                                bytes += chunk.len();
                            }
                        }
                        RequestResult {
                            duration,
                            status: Some(response.status()),
                            error: None,
                            bytes,
                        }
                    }
                    Err(e) => RequestResult {
                        duration,
                        status: None,
                        error: Some(e.to_string()),
                        bytes: 0,
                    },
                };
                let _ = tx.send(result).await;
                drop(permit);
            });
            count += 1;

            if let Some(qps) = args.query_per_second {
                tokio::time::sleep(Duration::from_secs_f64(1.0 / qps)).await;
            }
        }
    });

    drop(tx);

    let mut received = 0;
    while let Some(res) = rx.recv().await {
        stats.add(res);
        received += 1;
        if duration_limit.is_none() && received >= n_requests {
             break;
        }
    }
    stats.end_time = Instant::now();

    if args.output_format == OutputFormat::Text {
        print_summary(&stats, args.time_unit.as_deref());
    }
}
